    z-index: 0;
}

.news-card {
    position: relative;
    width: 45%;
    padding: 2rem;
    background: var(--morpho-bg-primary);
    border: 1px solid rgba(var(--morpho-text-primary-rgb), 0.1);
    border-radius: 4px;
    z-index: 1;
    transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.4s ease;

    /* Scroll-driven animation properties */
    view-timeline-name: --card-reveal;
    view-timeline-axis: block;
    animation-name: inference-reveal;
    animation-fill-mode: both;
    animation-timeline: --card-reveal;
    animation-range: entry 10% cover 40%;
}

